  gap: var(--g-spacing-2);
}

.meter__track {
  height: 8px;
  border-radius: var(--g-border-radius-l);
  background: var(--viz-series-1-track);
  overflow: hidden;
}

.meter__fill {
  height: 100%;
  background: var(--viz-series-1);
  border-radius: var(--g-border-radius-l);
}

/* --- List --- */

.list {
  flex: 1;
  min-height: 0;
