import {Icon, Text} from '@gravity-ui/uikit';
import {ArrowDown, ArrowUp} from '@gravity-ui/icons';

export interface StatTrend {
  /** preformatted signed value, e.g. "+12,4%" */
  value: string;
  direction: 'up' | 'down';
  /** whether the direction is good news (drives the color) */
  good: boolean;
